@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // create a new empty graph with the same vertex and edge types as the input graph
    Graph<V, E> graph = new Graph<>(target.getVertexType(), target.getEdgeType());

    // add all vertices to the graph
    for (V vertex : resultMap.values()) {
        graph.addVertex(vertex);
    }

    // add all edges to the graph
    for (E edge : target.getEdges()) {
        V sourceVertex = resultMap.get(edge.getSource());
        V targetVertex = resultMap.get(edge.getTarget());
        graph.addEdge(sourceVertex, targetVertex, edge);
    }

    // set the graph as the target graph
    target.setVertices(graph.getVertices());
    target.setEdges(graph.getEdges());
}

