    byte[] utf8Array = new byte[len];
    for (int i = 0; i < len; i++) {
        int c = str.charAt(index + i);
        if (c < 0x0080) {
            utf8Array[i] = (byte) c;
        } else if (c < 0x0800) {
            utf8Array[i] = (byte) (0xc0 | c >> 6);
            utf8Array[i + 1] = (byte) (0x80 | c & 0x3f);
        } else {
            utf8Array[i] = (byte) (0xe0 | c >> 12);
            utf8Array[i + 1] = (byte) (0x80 | (c >> 6) & 0x3f);
            utf8Array[i + 2] = (byte) (0x80 | c & 0x3f);
        }
    }
    return utf8Array.length;
}

