    if (byteOffset < 0 || byteOffset >= byteArrayValue.length) {
        throw new IllegalArgumentException("Invalid byte offset: " + byteOffset);
    }
    // Check if the byte length is valid
    if (byteLength < 0 || byteLength > byteArrayValue.length - byteOffset) {
        throw new IllegalArgumentException("Invalid byte length: " + byteLength);
    }
    // Resize the byte vector if necessary
    if (this.data.length < byteLength) {
        this.data = Arrays.copyOf(this.data, byteLength);
    }
    // Copy the bytes from the input array to the byte vector
    System.arraycopy(byteArrayValue, byteOffset, this.data, 0, byteLength);
    return this;
}

