public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
  // Calculate the midpoint of the box along the x-axis
  double midpointX = (box.getMinX() + box.getMaxX()) / 2;

  // Create two new boxes, one with the lower half of the original box
  // and one with the upper half
  Box2D lowerHalf = new Box2D(box.getMinX(), box.getMinY(), midpointX, box.getMaxY());
  Box2D upperHalf = new Box2D(midpointX, box.getMinY(), box.getMaxX(), box.getMaxY());

  return Pair.of(lowerHalf, upperHalf);
}

