            stackMapTableEntries.add(new StackMapTableEntry.FloatEntry((Float) type));
        } else if (type instanceof Long) {
            stackMapTableEntries.add(new StackMapTableEntry.LongEntry((Long) type));
        } else if (type instanceof Double) {
            stackMapTableEntries.add(new StackMapTableEntry.DoubleEntry((Double) type));
        } else if (type instanceof NullConstant) {
            stackMapTableEntries.add(new StackMapTableEntry.NullEntry());
        } else if (type instanceof UninitializedThis) {
            stackMapTableEntries.add(new StackMapTableEntry.UninitializedThisEntry());
        } else if (type instanceof ObjectType) {
            stackMapTableEntries.add(new StackMapTableEntry.ObjectEntry(((ObjectType) type).getClassName()));
        } else if (type instanceof UninitializedObjectType) {
            stackMapTableEntries.add(new StackMapTableEntry.UninitializedObjectEntry(((UninitializedObjectType) type).getOffset()));
        } else {
            throw new IllegalArgumentException("Unknown symbolic type: " + type);
        }
    }
}

