final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Check if the constant pool entry is a CONSTANT_Utf8 entry
    if (constantPoolEntryIndex >= 0 && constantPoolEntryIndex < constantPoolTable.length &&
            constantPoolTable[constantPoolEntryIndex] instanceof ConstantUtf8) {
        ConstantUtf8 constantUtf8 = (ConstantUtf8) constantPoolTable[constantPoolEntryIndex];
        if (charBuffer.length >= constantUtf8.length()) {
            // Buffer is large enough to hold the string
            for (int i = 0; i < constantUtf8.length(); i++) {
                charBuffer[i] = constantUtf8.charAt(i);
            }
            return new String(charBuffer, 0, constantUtf8.length());
        } else {
            // Buffer is too small, need to allocate a new array
            char[] newBuffer = Arrays.copyOf(charBuffer, constantUtf8.length());
            for (int i = 0; i < constantUtf8.length(); i++) {
                newBuffer[i] = constantUtf8.charAt(i);
            }
            return new String(newBuffer, 0, constantUtf8.length());
        }
    } else {
        // Not a CONSTANT_Utf8 entry, or index out of bounds
        throw new IndexOutOfBoundsException();
    }
}

