    boolean terminated = false;
    int index = 0;

    // iterate through the input characters
    while (index < input.length()) {
        char ch = input.charAt(index);

        // check if the character is a terminator
        for (int i = 0; i < terminators.length; i++) {
            if (ch == terminators[i]) {
                terminated = true;
                break;
            }
        }

        if (terminated) {
            break;
        }

        // process the character
        if (escaped) {
            token.append('\\');
            token.append(ch);
            escaped = false;
        } else {
            token.append(ch);
            if (ch == '\\') {
                escaped = true;
            }
        }

        index++;
    }

    return index == input.length() ? token.toString() : token.toString() + input.substring(index);
}

