public static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // check if both str and prefix are null
    if (str == null && prefix == null) {
        return true;
    }

    // check if str or prefix is null
    if (str == null || prefix == null) {
        return false;
    }

    // at this point, neither str nor prefix is null
    // check the length of prefix
    if (prefix.length() == 0) {
        return true;
    }

    // at this point, prefix is not null and has a positive length
    // check if prefix is a prefix of str
    if (ignoreCase) {
        return str.toLowerCase().startsWith(prefix.toLowerCase());
    } else {
        return str.startsWith(prefix);
    }
}

