public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Check if the name is already an abbreviation
    if (nameStart == 0 && buf.indexOf(' ') == -1) {
        return;
    }

    // Find the first letter of each name part
    int i = nameStart;
    while (i < buf.length() && buf.charAt(i) != ' ') {
        i++;
    }

    // Abbreviate the name
    buf.setCharAt(nameStart, Character.toUpperCase(buf.charAt(i)));
    buf.delete(nameStart + 1, i);
}

