private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (int i = 0; i < keys.size(); i++) {
        int currentKey = keys.get(i);
        int currentBound = currentKey - 1;
        for (int j = i + 1; j < keys.size(); j++) {
            if (keys.get(j) < currentKey) {
                currentBound = Math.min(currentBound, keys.get(j));
            }
        }
        lowerBounds.add(currentBound);
    }
    return lowerBounds;
}

private void pop(final String descriptor) {
    int numTypes = descriptor.length();
    for (int i = 0; i < numTypes; i++) {
        char type = descriptor.charAt(i);
        switch (type) {
            case 'L':
                popObject();
                break;
            case '[':
                popArray();
                break;
            case 'I':
                popInt();
                break;
            case 'J':
                popLong();
                break;
            case 'F':
                popFloat();
                break;
            case 'D':
                popDouble();
                break;
            default:
                throw new IllegalArgumentException("Invalid type descriptor: " + descriptor);
        }
    }
}

