private List<Integer> computeUpperBounds(List<K> keys) {
    // Initialize the minimum lower bound for each key to the maximum value
    int[] lowerBounds = new int[keys.size()];
    Arrays.fill(lowerBounds, Integer.MAX_VALUE);

    // Traverse the keys and update the minimum lower bound for each key
    for (int i = 0; i < keys.size(); i++) {
        K key = keys.get(i);
        int lowerBound = getLowerBound(key);
        lowerBounds[i] = Math.min(lowerBound, lowerBounds[i]);
    }

    // Return the computed upper bounds for each key
    return Arrays.asList(lowerBounds);
}

