public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] splitLine = line.split(",");
            if (splitLine.length < 11) {
                continue;
            }
            String threadName = splitLine[0].trim();
            String threadState = splitLine[1].trim();
            long threadId = Long.parseLong(splitLine[2].trim());
            int priority = Integer.parseInt(splitLine[3].trim());
            boolean daemon = Boolean.parseBoolean(splitLine[4].trim());
            long osThreadId = Long.parseLong(splitLine[5].trim());
            long startTime = Long.parseLong(splitLine[6].trim());
            long startCpuTime = Long.parseLong(splitLine[7].trim());
            long cpuTime = Long.parseLong(splitLine[8].trim());
            long userTime = Long.parseLong(splitLine[9].trim());
            long residentSize = Long.parseLong(splitLine[10].trim());
            boolean found = false;
            for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
                if (timeRange.includes(startCpuTime, cpuTime)) {
                    found = true;
                    break;
                }
            }
            if (found) {
                threadSnapshots.add(new ThreadSnapshot(threadName, threadState, threadId, priority, daemon, osThreadId, startTime, startCpuTime, cpuTime, userTime, residentSize));
            }
        }
    }
    return threadSnapshots;
}
